```

func (p *podWorkers) removeTerminatedWorker(uid types.UID) {
	status, ok := p.podSyncStatuses[uid]
	if !ok {
		// already forgotten, or forgotten too early
		klog.V(4).InfoS("Pod worker has been requested for removal but is not a known pod", "podUID", uid)
		return
	}

	if !status.finished {
		klog.V(4).InfoS("Pod worker has been requested for removal but is still not fully terminated", "podUID", uid)
		return
	}

	klog.V(4).InfoS("Pod has been terminated and is no longer known to the kubelet, remove all history", "podUID", uid)
	delete(p.podSyncStatuses, uid)
	delete(p.podUpdates, uid)
	delete(p.lastUndeliveredWorkUpdate, uid)
	if ch, ok := p.waitingStaticPods[uid]; ok {
		close(ch)
	}
	delete(p.waitingStaticPods, uid)

}

func (p *podWorkers) SetStaticPodWaiting(uid types.UID, ch chan<- struct{}) {
	p.podLock.Lock()
	defer p.podLock.Unlock()
	p.waitingStaticPods[uid] = ch
}

func (p *podWorkers) IsStaticPodNeedWaiting(uid types.UID) bool {
	p.podLock.Lock()
	defer p.podLock.Unlock()
	if status, ok := p.podSyncStatuses[uid]; ok {
		return status.IsTerminated() || status.IsTerminationRequested() || status.IsTerminationStarted()
	}
	return false
}

func (p *podWorkers) HasStaticPodWaiting(uid types.UID) bool {
	p.podLock.Lock()
	defer p.podLock.Unlock()
	if _, ok := p.waitingStaticPods[uid]; ok {
		return true
	}
	return false
}
